fn flip_case(s: Vec<char>) -> Vec<char> {
    let mut result = Vec::with_capacity(s.len()); // Preallocate memory for the result vector

    for &c in &s {
        if c.is_ascii_alphabetic() {
            // Flip case: if it's lowercase, convert to uppercase, and vice versa
            if c.is_ascii_lowercase() {
                result.push(c.to_ascii_uppercase());
            } else {
                result.push(c.to_ascii_lowercase());
            }
        } else {
            // Non-alphabetic characters remain unchanged
            result.push(c);
        }
    }

    result
}